# init: pairs G-C, unpaired A, with caps
pair = [-1]*n
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

def hairpin_loops():
    loops=[]
    for i in range(n):
        if pair[i]!=-1 and i<pair[i]:
            j=pair[i]
            if all(pair[k]==-1 for k in range(i+1,j)):
                loops.append((i,j,sum(1 for k in range(i+1,j) if pair[k]==-1)))
    return loops

seq=['A']*n
for i in range(n):
    if pair[i]!=-1 and i<pair[i]:
        seq[i]='G'; seq[pair[i]]='C'
for (i,j,L) in hairpin_loops():
    if L==4:
        seq[i+1]='G';seq[i+2]='A';seq[i+3]='A';seq[i+4]='A'
    elif L==3:
        seq[i+1]='G';seq[i+2]='A';seq[i+3]='A'
    seq[i]='G';seq[j]='C'

def fold(s):
    return RNA.fold_compound(s).mfe()[0]
def dist(s):
    return RNA.bp_distance(fold(s),target)

cur=''.join(seq)
cur_d=dist(cur); best,best_d=cur,cur_d
print("init dist",cur_d, cur)

deadline=time.time()+120
random.seed(1)
while time.time()<deadline and best_d>0:
    c=list(cur)
    for _ in range(random.choice([1,1,2,2,3])):
        i=random.randrange(n)
        if pair[i]==-1:
            c[i]=random.choice('ACGU')
        else:
            # keep WC, mutate this pair identity
            j=pair[i]
            p=random.choice(['GC','CG','AU','UA','GU','UG'])
            c[i]=p[0]; c[j]=p[1]
    c=''.join(c)
    d=dist(c)
    if d<cur_d or (d==cur_d and random.random()<0.4):
        cur,cur_d=c,d
        if d<best_d: best,best_d=c,d
print("best dist",best_d)
print(best)
st=fold(best)
print(st)
print(target)
