import RNA, random, time, multiprocessing as mp
target = "((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..))))"
n = len(target)
pair = [-1]*n
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

def fold(s): return RNA.fold_compound(s).mfe()[0]
def dist(s): return RNA.bp_distance(fold(s),target)

def run(seed):
    random.seed(seed)
    seq=['A']*n
    for i in range(n):
        if pair[i]!=-1 and i<pair[i]:
            seq[i]='G'; seq[pair[i]]='C'
    cur=''.join(seq)
    cur_d=dist(cur); best,best_d=cur,cur_d
    deadline=time.time()+25
    while time.time()<deadline and best_d>0:
        c=list(cur)
        for _ in range(random.choice([1,1,2,2,3])):
            i=random.randrange(n)
            if pair[i]==-1:
                r=random.random()
                c[i]='A' if r<0.6 else random.choice('ACGU')
            else:
                j=pair[i]
                p=random.choice(['GC','CG','AU','UA','GU','UG'])
                c[i]=p[0]; c[j]=p[1]
        c=''.join(c)
        d=dist(c)
        if d<cur_d or (d==cur_d and random.random()<0.45):
            cur,cur_d=c,d
            if d<best_d: best,best_d=c,d
    return best,best_d

sols=set()
with mp.Pool(40) as p:
    for b,d in p.imap_unordered(run, range(400)):
        if d==0:
            sols.add(b)
print("ndistinct",len(sols))
sols=sorted(sols)
for s in sols[:20]:
